UPDATE monitor_task
SET name = #{name}, datasource_id = #{datasourceId}, sql_script = #{sqlScript},
    cron_expression = #{cronExpression}, is_active = #{isActive}, result_type = #{resultType},
    alarm_threshold_rule = #{alarmThresholdRule}, chart_config = #{chartConfig},
    is_store_data = #{isStoreData}, update_time = #{updateTime}
WHERE id = #{id}
